UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/CostaBrava.unity", UnityEditor.SceneManagement.OpenSceneMode.Single);
var sb = new System.Text.StringBuilder();
var garage = UnityEngine.Object.FindObjectOfType<VehicleGarage>();
if (garage == null) return "no garage";
sb.AppendLine("player pos=" + garage.transform.position);
var cam = Camera.main;
if (cam) sb.AppendLine("camera pos=" + cam.transform.position);
foreach (var g in UnityEngine.Object.FindObjectsByType<Transform>(FindObjectsSortMode.None))
{
    if (g.name == "AURORA aero kit" || g.name == "AURORA light kit")
    {
        var owner = g.parent;
        sb.AppendLine(g.name + " owner=" + (owner ? owner.name : "?") + " pos=" + g.position + " localPos=" + g.localPosition);
    }
    if (g.name.StartsWith("BODY / "))
    {
        var owner = g.parent;
        sb.AppendLine(g.name + " owner=" + (owner ? owner.name : "?") + " active=" + g.gameObject.activeSelf + " pos=" + g.position);
    }
}
Debug.Log("PROBE6 " + sb.ToString().Replace("\r", "").Replace("\n", " || "));
return sb.ToString();
